<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class mbuyermodel extends CI_Model {    function fnGetAllBuyer($VarStatus = 1, $VarCompanyId)    {        return $this->db->select('id,buyername')->from(KN_MASTER_BUYER)->where(array('status' => $VarStatus))->get()->result();    }    function fnGetInfo($VarData, $VarStatus, $VarId = '')    {        $this->db->select('id,buyername,status')->from(KN_MASTER_BUYER);        if ($VarData <> '') {            $ArrWhere['buyername'] = $VarData;        }        if ($VarStatus <> '') {            $this->db->where_in('status', array($VarStatus));        } else {            $this->db->where_in('status', array(1, 2));        }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if (!empty($ArrWhere)) {            $this->db->where($ArrWhere);        }        return $this->db->get()->result();    }    function fnCheck($VarData = '', $VarId = '') {        $this->db->from(KN_MASTER_BUYER);        $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarData <> '') {            $ArrWhere['buyername'] = $VarData;        }        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function saveInfo($ArrData)    {        $VarCompanyId = $ArrData['companyid'];        $VarId = $ArrData['id'];        $ArrResult=[];        if($VarId=="") {            $ArrCheckExist = $this->fnGetInfo($ArrData['buyername'], 1);            if (empty($ArrCheckExist)) {                unset($ArrData['id']);                $this->db->insert(KN_MASTER_BUYER, $ArrData);                $VarInsId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarInsId;                $ArrResult['eid'] = urlencode(base64_encode($VarInsId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This Buyer already exists!!";            }        } else {            $ArrCheckExist = $this->fnCheck($ArrData['buyername'], $VarId);            if (empty($ArrCheckExist)) {                if ($this->db->update(KN_MASTER_BUYER, $ArrData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data!';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This Buyer already exists!!";            }        }        return $ArrResult;    }    function fnCount($VarBuyer = '', $VarStatus = '', $VarAfilter = '')    {        $ArrWhere                   = array();        if($VarBuyer<>'') {            $ArrWhere[]             = "b.buyername like '%".$VarBuyer."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "b.status=".$VarStatus;        } else {            $ArrWhere[]             = "b.status in(1,2)";        }        if($VarAfilter<>'') {            $ArrWhere[]             = "b.buyername LIKE '".$VarAfilter."%'";        }        $VarWhere                   = '';        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        if(@$ArrWhere[0]<>'') {            $VarWhere = 'WHERE ' . implode(" and ", $ArrWhere) . " AND b.companyid = " . $ArrUserLoggedInfo['companyid'] . " ";        }        $VarSqlLab = "SELECT count(1) as trec  FROM " . KN_MASTER_BUYER . " AS b INNER JOIN " . KN_USERS . " AS u ON b.updatedby = u.id " . $VarWhere;        $ObjRows					= $this->db->query($VarSqlLab)->row();        return $ObjRows->trec;    }    function fnList($VarBuyer = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder, $VarAfilter = '')    {        $VarSortOrder				= ($VarSortOrder=='desc')? 'desc' : 'asc';        $VarSortCols = array('buyername', 'contactname', 'status', 'b.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'b.dateupdated';        $VarLimitInfo				= $VarLimit;        if($offset>=1) {$VarLimitInfo	 = $offset.",".$VarLimit;}        $ArrWhere                   = array();        if($VarBuyer<>'') {            $ArrWhere[]             = "b.buyername like '%".$VarBuyer."%'";        }        if($VarAfilter<>'') {            $ArrWhere[]             = "b.buyername LIKE '".$VarAfilter."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "b.status=".$VarStatus;        } else {            $ArrWhere[]             = "b.status in(1,2)";        }        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarWhere                   = '';        if(@$ArrWhere[0]<>'') {            $VarWhere = 'WHERE ' . implode(" and ", $ArrWhere) . " AND b.companyid = " . $ArrUserLoggedInfo['companyid'] . " ";        }        $VarSqlLab = "SELECT b.id,b.buyername,DATE_FORMAT(b.dateupdated,\"%d-%m-%Y %H:%i:%s\") AS formattedDateUpdated,b.status,contactname FROM " . KN_MASTER_BUYER . " AS b INNER JOIN " . KN_USERS . " AS u ON b.updatedby = u.id " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder . " limit " . $VarLimitInfo;        $ObjResult					= $this->db->query($VarSqlLab);        return $ObjResult;    }    function fnChangeComStat($checkboxids,$optvalue) {        $Arrids =  json_decode($checkboxids,true);        $this->db->where_in('id',$Arrids);        if($this->db->update(KN_MASTER_BUYER,array('status' => $optvalue))) {            return true;        }        return false;    }}   